contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test entry
    function run(address addr1, address addr2, bytes32 digest, bytes32 r, bytes32 s, bytes32 pubX, bytes32 pubY, bytes memory outpoint, bytes memory script, uint256 utxoSize, uint256 requestedFee, bytes32 txid, bool wasFraud) public payable {
        require(addr1 != address(0) && addr2 != address(0));

        // Record approvals before any state-changing calls
        bool before1 = c.approvedToLog(addr1); if (__ESBMC_reverted()) return;
        bool before2 = c.approvedToLog(addr2); if (__ESBMC_reverted()) return;
        bool beforeThis = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;

        // Make a set of logging calls. Each is a top-level statement that may change c's state.
        bool ok1;
        bool v1 = c.logCreated(addr2); bool __rev0 = __ESBMC_reverted(); if (__rev0) { ok1 = false; } else { ok1 = v1; }

        bool ok2;
        bool v2 = c.logRedemptionRequested(addr2, digest, utxoSize, script, requestedFee, outpoint); bool __rev1 = __ESBMC_reverted(); if (__rev1) { ok2 = false; } else { ok2 = v2; }

        bool ok3;
        bool v3 = c.logGotRedemptionSignature(digest, r, s); bool __rev2 = __ESBMC_reverted(); if (__rev2) { ok3 = false; } else { ok3 = v3; }

        bool ok4;
        bool v4 = c.logRegisteredPubkey(pubX, pubY); bool __rev3 = __ESBMC_reverted(); if (__rev3) { ok4 = false; } else { ok4 = v4; }

        bool ok5;
        bool v5 = c.logSetupFailed(); bool __rev4 = __ESBMC_reverted(); if (__rev4) { ok5 = false; } else { ok5 = v5; }

        bool ok6;
        bool v6 = c.logFraudDuringSetup(); bool __rev5 = __ESBMC_reverted(); if (__rev5) { ok6 = false; } else { ok6 = v6; }

        bool ok7;
        bool v7 = c.logFunded(); bool __rev6 = __ESBMC_reverted(); if (__rev6) { ok7 = false; } else { ok7 = v7; }

        bool ok8;
        bool v8 = c.logCourtesyCalled(); bool __rev7 = __ESBMC_reverted(); if (__rev7) { ok8 = false; } else { ok8 = v8; }

        bool ok9;
        bool v9 = c.logStartedLiquidation(wasFraud); bool __rev8 = __ESBMC_reverted(); if (__rev8) { ok9 = false; } else { ok9 = v9; }

        bool ok10;
        bool v10 = c.logRedeemed(txid); bool __rev9 = __ESBMC_reverted(); if (__rev9) { ok10 = false; } else { ok10 = v10; }

        bool ok11;
        bool v11 = c.logLiquidated(); bool __rev10 = __ESBMC_reverted(); if (__rev10) { ok11 = false; } else { ok11 = v11; }

        bool ok12;
        bool v12 = c.logExitedCourtesyCall(); bool __rev11 = __ESBMC_reverted(); if (__rev11) { ok12 = false; } else { ok12 = v12; }

        // Read approvals after calls
        bool after1 = c.approvedToLog(addr1); if (__ESBMC_reverted()) return;
        bool after2 = c.approvedToLog(addr2); if (__ESBMC_reverted()) return;
        bool afterThis = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;

        // General rule: approvals for observed addresses unchanged
        bool approvalsUnchanged = (before1 == after1) && (before2 == after2) && (beforeThis == afterThis);

        // Any logging call that returned true implies this contract was approved before the calls
        bool anyReturnedTrue = ok1 || ok2 || ok3 || ok4 || ok5 || ok6 || ok7 || ok8 || ok9 || ok10 || ok11 || ok12;
        bool returnedImpliesApproved = !anyReturnedTrue || beforeThis;

        assert(approvalsUnchanged && returnedImpliesApproved);
    }

    receive() external payable {}
}

