pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(address addr1, address addr2, bytes32 digest, bytes32 r, bytes32 s, bytes32 pubX, bytes32 pubY, bytes memory outpoint, bytes memory script, uint256 utxoSize, uint256 requestedFee, bytes32 txid, bool wasFraud) internal {
        vm.assume(addr1 != address(0) && addr2 != address(0));
        bool before1;
        try c.approvedToLog(addr1) returns (bool __r) { before1 = __r; } catch { return; }
        bool before2;
        try c.approvedToLog(addr2) returns (bool __r) { before2 = __r; } catch { return; }
        bool beforeThis;
        try c.approvedToLog(address(this)) returns (bool __r) { beforeThis = __r; } catch { return; }
        bool ok1;
        try c.logCreated(addr2) returns (bool v1) { ok1 = v1; } catch { ok1 = false; }
        bool ok2;
        try c.logRedemptionRequested(addr2, digest, utxoSize, script, requestedFee, outpoint) returns (bool v2) { ok2 = v2; } catch { ok2 = false; }
        bool ok3;
        try c.logGotRedemptionSignature(digest, r, s) returns (bool v3) { ok3 = v3; } catch { ok3 = false; }
        bool ok4;
        try c.logRegisteredPubkey(pubX, pubY) returns (bool v4) { ok4 = v4; } catch { ok4 = false; }
        bool ok5;
        try c.logSetupFailed() returns (bool v5) { ok5 = v5; } catch { ok5 = false; }
        bool ok6;
        try c.logFraudDuringSetup() returns (bool v6) { ok6 = v6; } catch { ok6 = false; }
        bool ok7;
        try c.logFunded() returns (bool v7) { ok7 = v7; } catch { ok7 = false; }
        bool ok8;
        try c.logCourtesyCalled() returns (bool v8) { ok8 = v8; } catch { ok8 = false; }
        bool ok9;
        try c.logStartedLiquidation(wasFraud) returns (bool v9) { ok9 = v9; } catch { ok9 = false; }
        bool ok10;
        try c.logRedeemed(txid) returns (bool v10) { ok10 = v10; } catch { ok10 = false; }
        bool ok11;
        try c.logLiquidated() returns (bool v11) { ok11 = v11; } catch { ok11 = false; }
        bool ok12;
        try c.logExitedCourtesyCall() returns (bool v12) { ok12 = v12; } catch { ok12 = false; }
        bool after1;
        try c.approvedToLog(addr1) returns (bool __r) { after1 = __r; } catch { return; }
        bool after2;
        try c.approvedToLog(addr2) returns (bool __r) { after2 = __r; } catch { return; }
        bool afterThis;
        try c.approvedToLog(address(this)) returns (bool __r) { afterThis = __r; } catch { return; }
        bool approvalsUnchanged = (before1 == after1) && (before2 == after2) && (beforeThis == afterThis);
        bool anyReturnedTrue = ok1 || ok2 || ok3 || ok4 || ok5 || ok6 || ok7 || ok8 || ok9 || ok10 || ok11 || ok12;
        bool returnedImpliesApproved = !anyReturnedTrue || beforeThis;
        assertTrue(approvalsUnchanged && returnedImpliesApproved);
    }

    function testFuzz_run(address addr1, address addr2, bytes32 digest, bytes32 r, bytes32 s, bytes32 pubX, bytes32 pubY, bytes memory outpoint, bytes memory script, uint256 utxoSize, uint256 requestedFee, bytes32 txid, bool wasFraud) public {
        vm.assume(addr1.code.length == 0 && uint160(addr1) > 0xffff && addr1 != address(this) && addr1 != address(c) && addr1 != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && addr1 != 0x000000000000000000636F6e736F6c652e6c6f67 && addr1 != 0x4e59b44847b379578588920cA78FbF26c0B4956C && addr1 != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(addr2.code.length == 0 && uint160(addr2) > 0xffff && addr2 != address(this) && addr2 != address(c) && addr2 != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && addr2 != 0x000000000000000000636F6e736F6c652e6c6f67 && addr2 != 0x4e59b44847b379578588920cA78FbF26c0B4956C && addr2 != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(addr1, addr2, digest, r, s, pubX, pubY, outpoint, script, utxoSize, requestedFee, txid, wasFraud);
    }

    receive() external payable {}
}
